// Des: Tests for st-page-inde: upsert, read back, log, reopen
// Flo: temp dir > open > set twice > get > log > reopen > assert
// I/O: rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inde = @import("st-page-inde.zig");
test "page upsert keeps one row, values updated, survives reopen" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); { var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); try std.testing.expect(try inde.pageGetz(&dbzz, aren.allocator(), "http://a/x") == null); const rowz: inde.Rowz = .{ .hexz = "aa", .etag = "\"e1\"", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 10, .next = 20 }; try inde.pageSetz(&dbzz, "http://a/x", rowz); var two2 = rowz; two2.hexz = "bb"; two2.fetc = 11; try inde.pageSetz(&dbzz, "http://a/x", two2); } var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); const got2 = (try inde.pageGetz(&dbzz, aren.allocator(), "http://a/x")).?; try std.testing.expectEqualStrings("bb", got2.hexz); try std.testing.expectEqualStrings("\"e1\"", got2.etag); try std.testing.expectEqual(@as(i64, 11), got2.fetc); }
test "log rows append" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); const rowz: inde.Logz = .{ .urlz = "http://a/x", .code = 200, .tier = 1, .vend = "", .cred = 0, .micr = 0, .robo = "allow", .timz = 1, .note = "" }; try inde.logzAddz(&dbzz, rowz); try inde.logzAddz(&dbzz, rowz); try std.testing.expectEqual(@as(i64, 2), try inde.logzCont(&dbzz)); }
test "migration 12 and 13: pack verify and vendor, purge state, DB ledger, failover state" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); try std.testing.expectEqual(@as(i64, 16), try dbzz.verzGetz()); try dbzz.exec("INSERT INTO mspl(vend,stmt) VALUES('neon','x');"); try dbzz.exec("INSERT INTO cont(cidz,kind,name,phon,pho2,mail,addr,prov,desc,phsh,mask,site,urlz,fors,lasz) VALUES('c','dealer','n','p','q','m','a','v','d','h',0,'s','u',1,2); UPDATE carz SET cont='c' WHERE 1=0;"); try dbzz.exec("INSERT INTO carp(urlz,timz,pric) VALUES('u',1,2); INSERT INTO carr(wkzz,make,modl,year,powr,cond,cont,pmed,pq25,pq75,kmed,domm) VALUES(1,'a','b',2020,'GAS','used',1,2,3,4,5,6);"); try dbzz.exec("INSERT INTO pack(hexz,packk,offs,lenz) VALUES('h','runs/x',1,2); INSERT INTO purg(packz,timz,ents) VALUES('runs/x',5,1); INSERT INTO dbcl(urlh,byts) VALUES('u',100); INSERT INTO fovr(name,fail,unti,live) VALUES('b2zz',0,0,0);"); var stmt = try dbzz.prep("SELECT vfyz,vend FROM pack WHERE hexz='h';"); defer stmt.fini(); try std.testing.expect(try stmt.step()); try std.testing.expectEqual(@as(i64, 0), stmt.colzIntz(0)); try std.testing.expectEqualStrings("", stmt.colzText(1)); var sta2 = try dbzz.prep("SELECT stat FROM purg WHERE packz='runs/x';"); defer sta2.fini(); try std.testing.expect(try sta2.step()); try std.testing.expectEqual(@as(i64, 1), sta2.colzIntz(0)); }
